local M = class("SimulateSelectRoleModel", LikeOO.OODataBase)

local roleQualityList = {
    --红
    "UI_SimulateLift_RGlow001",
    --黄
    "UI_SimulateLift_YGlow001",
    --紫
    "UI_SimulateLift_PGlow001",
    --蓝
    "UI_SimulateLift_BGlow001",
    --绿
    "UI_SimulateLift_GGlow001",
}

function M:onCreate()
    M.super.onCreate(self)
    self:initData()
    self:getData("game_start",{open_id = self.m_open_id, version = self.m_version})
end

function M:initData()
    self.m_open_id = self.m_params.open_id
    self.m_version = self.m_params.version
    self.m_roleQualityList = roleQualityList
    -- 剩余随机的次数
   self:refreshResidueCount(self.m_params.reset_times)
end

function M:refreshResidueCount(m_reset_times)
    self.m_reset_times = m_reset_times or 0
    local configCount = ConfigManager:getCommonValueById(669) or 10
    local residueCount = configCount - self.m_reset_times
    residueCount = residueCount > 0 and residueCount or 0
    self.m_resetCount = residueCount
end

function M:reduceResetCount()
    if self.m_resetCount <= 0 then
        return
    end
    self.m_resetCount = self.m_resetCount - 1
end

function M:onEnter()
    self:refreshData(self.m_data)
end

function M:getAttributeLevel(attributeValue)
    local attributeScope = ConfigManager:getCommonValueById(650) or {}
    if table.nums(attributeScope) <= 0 then
        return 5
    end
    if attributeValue < attributeScope[1] then
        return 5
    elseif (attributeValue >= attributeScope[1] ) and (attributeValue <= attributeScope[2]) then
        return 4
    elseif (attributeValue > attributeScope[2] ) and (attributeValue <= attributeScope[3]) then
        return 3
    elseif (attributeValue > attributeScope[3] ) and (attributeValue <= attributeScope[4]) then
        return 2
    elseif attributeValue > attributeScope[4] then
        return 1
    end
    return 5
end

function M:refreshData(data)
    self:refreshResidueCount(data.reset_times)
    self:refreshRoleData(data.role_options)
end

function M:refreshRoleData(role_options)
    self.m_itemDatas = {}
    local roleData = role_options
    local roleXlsxData = ConfigManager:getCfgByName("reopen_character")
    local attributeXlsxData = ConfigManager:getCfgByName("reopen_enumeration")
    local attributeCount = 4
    for strRoleId, attributeData in pairs(roleData) do
        local roleId = tonumber(strRoleId)
        -- 排属性
        local templateList = {}
        local attribute = {}
        for attributeId, attributeValue in pairs(attributeData) do
            table.insert(templateList, {id = tonumber(attributeId), value = attributeValue})
        end
        table.sort(templateList, function(tempitemData1, tempitemData2) return tempitemData1.id < tempitemData2.id end)
        local allScore = 0
        local qualityColourValues = GlobalConfig.SimulateQualityColourValues
        local qualityValues = GlobalConfig.SimulateQualityValues
        local bgQualityName = GlobalConfig.SimulateBgQualityName
        for index = 1, attributeCount do
            local itemAttribute = templateList[index]
            local itemAttXlsxData = attributeXlsxData[itemAttribute.id]
            local itemAttributeLevel = self:getAttributeLevel(itemAttribute.value)
            table.insert(attribute,{
                level = itemAttributeLevel,
                name = itemAttXlsxData.name,
                value = itemAttribute.value,
                color = qualityColourValues[itemAttributeLevel], 
                levelName = qualityValues[itemAttributeLevel], 
            })
            allScore = allScore + itemAttribute.value
        end
        -- 角色信息
        local averageScore = math.floor(allScore / attributeCount)
        local scoreLevel = self:getAttributeLevel(averageScore)
        local curRoleData = roleXlsxData[roleId] or {}
        table.insert(self.m_itemDatas, {
            bgName = bgQualityName[scoreLevel],
            name = Language:getTextByKey(curRoleData.name),
            attribute = attribute,
            roleId = roleId,
            scoreLevel = scoreLevel,
        })
    end
    
    --self.m_itemDatas = {
