    --                value = 10,
    --                color = QualityColourValues[1],         --- 和level挂钩
    --                levelName = QualityValues[1],                --- 和level挂钩
    --            },
    --            [2] = {},
    --            [3] = {},
    --            [4] = {},
    --        },
    --    },
    --}
end


return M